import { useEffect, useState } from 'react';
import FinancesDetailsTable from '../FinancesDetailsTable';
import FinancesSummaryCards from '../FinancesSummaryCards';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import type { FinanceBenefitsMePayload } from '@/features/finances/types/finance-employee.types';
import {
    PLACEHOLDER_DEDUCTIONS_ROWS,
    PLACEHOLDER_ENTITLEMENTS_ROWS,
} from '../../data/financesPlaceholderDetails';
import { FINANCE_TAB_PLACEHOLDER_CARDS } from '../../data/financeTabs';

export default function FinancesTabPlaceholder() {
    const [payload, setPayload] = useState<FinanceBenefitsMePayload | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            setLoading(true);
            setError(null);
            try {
                const res = await apiGet<{ data: FinanceBenefitsMePayload }>({
                    endpoint: endpoints.financeEmployee.benefitsMe,
                });
                if (cancelled) return;
                setPayload(res.data.data ?? null);
            } catch {
                if (!cancelled) {
                    setError('تعذر تحميل تفاصيل الراتب. تأكد من ربط بريد حسابك بسجل الموظف.');
                    setPayload(null);
                }
            } finally {
                if (!cancelled) setLoading(false);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    const cards = payload?.summary_cards?.length ? payload.summary_cards : FINANCE_TAB_PLACEHOLDER_CARDS;
    const entitlements = payload?.entitlements?.length ? payload.entitlements : PLACEHOLDER_ENTITLEMENTS_ROWS;
    const deductions = payload?.deductions?.length ? payload.deductions : PLACEHOLDER_DEDUCTIONS_ROWS;

    return (
        <div className="w-full mt-6 space-y-6 font-cairo">
            {error && <p className="text-sm text-red-600">{error}</p>}
            {loading ? (
                <p className="text-center text-[#625E74] py-6">جاري التحميل…</p>
            ) : (
                <>
                    <FinancesSummaryCards cards={cards} />
                    <FinancesDetailsTable title="تفاصيل المستحقات" rows={entitlements} />
                    <FinancesDetailsTable title="تفاصيل الخصومات" rows={deductions} />
                </>
            )}
        </div>
    );
}
