import { useCallback, useRef, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar, type DataTableToolbarProps } from './data-table-toolbar';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { createPayrollListColumns } from './columns';
import type { FinancePayrollMonthRow, PayrollStatementTableRow } from '@/features/finances/types/finance-employee.types';
import { formatMoneySar } from '@/features/finances/utils/formatMoney';

function normalizeSalaryHistory(raw: unknown): FinancePayrollMonthRow[] {
    if (Array.isArray(raw)) return raw as FinancePayrollMonthRow[];
    if (raw && typeof raw === 'object') return Object.values(raw) as FinancePayrollMonthRow[];
    return [];
}

function mapHistoryToRows(rows: FinancePayrollMonthRow[]): PayrollStatementTableRow[] {
    return rows.map((r, index) => ({
        id: `${r.pay_date ?? r.month}-${index}`,
        month: r.month,
        payDate: r.pay_date ?? '—',
        netSalary: formatMoneySar(r.net_salary),
        status: 'مدفوع',
    }));
}

const PayrollList = () => {
    const [data, setData] = useState<PayrollStatementTableRow[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const allRowsRef = useRef<PayrollStatementTableRow[]>([]);
    const loadedRef = useRef(false);

    const fetchData = useCallback(async (options: FetchDataOptions) => {
        setIsLoading(true);
        try {
            if (!loadedRef.current) {
                const response = await apiGet<{ data: { salary_history: FinancePayrollMonthRow[] } }>({
                    endpoint: endpoints.financeEmployee.payrollStatementsMe,
                });
                const history = normalizeSalaryHistory(response.data.data?.salary_history);
                const mapped = mapHistoryToRows(history);
                allRowsRef.current = mapped;
                loadedRef.current = true;
            }

            const q = (options.globalFilter || '').trim().toLowerCase();
            const filtered = q
                ? allRowsRef.current.filter(
                      (row) =>
                          row.month.toLowerCase().includes(q) ||
                          row.payDate.includes(q) ||
                          row.netSalary.toLowerCase().includes(q),
                  )
                : allRowsRef.current;

            const pageSize = options.pageSize || 10;
            const start = options.pageIndex * pageSize;
            setData(filtered.slice(start, start + pageSize));
            setPageCount(Math.max(1, Math.ceil(filtered.length / pageSize)));
            setTotalCount(filtered.length);
        } catch (error) {
            console.error('Error fetching payroll statements:', error);
            setData([]);
            setPageCount(1);
            setTotalCount(0);
        } finally {
            setIsLoading(false);
        }
    }, []);

    return (
        <div className="mb-10 mt-4 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <DataTable
                columns={createPayrollListColumns()}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={(props: DataTableToolbarProps) => <DataTableToolbar {...props} />}
                isLoading={isLoading}
            />
        </div>
    );
};

export default PayrollList;
