import { useEffect, useMemo, useState } from 'react';
import FinancesSummaryCards from '../FinancesSummaryCards';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import type { FinanceAnnualSummaryRow } from '@/features/finances/types/finance-employee.types';
import { formatMoneySar } from '@/features/finances/utils/formatMoney';

function formatMoney(n: number) {
    return n.toLocaleString('en-US', { maximumFractionDigits: 2 });
}

type DeductionMonthRow = { month: string; total_deductions?: number | string };

export default function DeductionsAndTaxesTab() {
    const [annualRows, setAnnualRows] = useState<FinanceAnnualSummaryRow[]>([]);
    const [totalSalary, setTotalSalary] = useState(0);
    const [insurance, setInsurance] = useState(0);
    const [monthlyDeductions, setMonthlyDeductions] = useState<DeductionMonthRow[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            setLoading(true);
            setError(null);
            try {
                const [payrollRes, dedRes] = await Promise.all([
                    apiGet<{ data: { annual_summary?: FinanceAnnualSummaryRow[] } }>({
                        endpoint: endpoints.financeEmployee.payrollStatementsMe,
                    }),
                    apiGet<{
                        data: {
                            total_salary?: number | string;
                            insurance?: number | string;
                            deductions?: DeductionMonthRow[];
                        };
                    }>({ endpoint: endpoints.financeEmployee.deductionsMe }),
                ]);
                if (cancelled) return;
                const ann = payrollRes.data.data?.annual_summary;
                setAnnualRows(Array.isArray(ann) ? ann : ann && typeof ann === 'object' ? Object.values(ann) : []);
                const d = dedRes.data.data;
                setTotalSalary(Number(d?.total_salary ?? 0));
                setInsurance(Number(d?.insurance ?? 0));
                setMonthlyDeductions(Array.isArray(d?.deductions) ? d.deductions : []);
            } catch {
                if (!cancelled) {
                    setError('تعذر تحميل بيانات الخصومات.');
                    setAnnualRows([]);
                }
            } finally {
                if (!cancelled) setLoading(false);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    const currentYear = String(new Date().getFullYear());

    const summaryCards = useMemo(() => {
        const yearRow = annualRows.find((r) => r.year === currentYear);
        const totalTaxesYear = yearRow?.total_taxes ?? 0;
        const other = Math.max(0, Number(totalTaxesYear) - insurance);

        return [
            {
                title: `إجمالي الدخل (${currentYear})`,
                value: formatMoneySar(yearRow?.total_income ?? totalSalary),
                unit: 'ريال',
            },
            {
                title: 'التأمينات والتأمين المسجل',
                value: formatMoneySar(insurance),
                unit: 'ريال',
            },
            {
                title: 'خصومات أخرى (مسجّلة)',
                value: formatMoneySar(other),
                unit: 'ريال',
            },
        ];
    }, [annualRows, currentYear, insurance, totalSalary]);

    const tableRows = useMemo(() => {
        if (annualRows.length > 0) {
            return annualRows.map((r) => ({
                year: r.year,
                totalIncome: r.total_income,
                totalTaxes: r.total_taxes,
            }));
        }
        const byYear = new Map<string, { income: number; taxes: number }>();
        const basic = totalSalary / 12;
        monthlyDeductions.forEach((m) => {
            const parts = (m.month || '').trim().split(/\s+/);
            const y = parts[parts.length - 1];
            if (!y || Number.isNaN(Number(y))) return;
            const prev = byYear.get(y) ?? { income: 0, taxes: 0 };
            prev.taxes += Number(m.total_deductions ?? 0);
            prev.income += basic;
            byYear.set(y, prev);
        });
        return [...byYear.entries()]
            .map(([year, v]) => ({ year, totalIncome: v.income, totalTaxes: v.taxes }))
            .sort((a, b) => Number(b.year) - Number(a.year));
    }, [annualRows, monthlyDeductions, totalSalary]);

    return (
        <div className="w-full mt-6 space-y-6 font-cairo">
            {error && <p className="text-sm text-red-600">{error}</p>}
            <FinancesSummaryCards cards={summaryCards} />

            <div className="rounded-xl border border-[#E8E7EA] bg-white-blue-50 shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A] overflow-hidden">
                <div className="px-4 py-3 border-b border-[#E8E7EA] bg-white-blue-100/80">
                    <h3 className="text-base font-bold text-primery-blue-500">تقرير الضرائب والخصومات السنوية</h3>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full min-w-[480px] text-sm">
                        <thead>
                            <tr className="bg-white-blue-100">
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">
                                    السنة
                                </th>
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">
                                    إجمالي الدخل
                                </th>
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">
                                    إجمالي الخصومات
                                </th>
                            </tr>
                        </thead>
                        <tbody>
                            {loading ? (
                                <tr>
                                    <td colSpan={3} className="px-4 py-8 text-center text-[#625E74]">
                                        جاري التحميل…
                                    </td>
                                </tr>
                            ) : tableRows.length === 0 ? (
                                <tr>
                                    <td colSpan={3} className="px-4 py-8 text-center text-[#625E74]">
                                        لا توجد بيانات كافية لعرض التقرير السنوي.
                                    </td>
                                </tr>
                            ) : (
                                tableRows.map((row) => (
                                    <tr
                                        key={row.year}
                                        className="border-t border-[#E8E7EA] text-[#625E74] hover:bg-white-blue-100/50"
                                    >
                                        <td className="px-4 py-3 font-medium tabular-nums">{row.year}</td>
                                        <td className="px-4 py-3 tabular-nums">{formatMoney(row.totalIncome)} ريال</td>
                                        <td className="px-4 py-3 tabular-nums">{formatMoney(row.totalTaxes)} ريال</td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}
