import { ColumnDef } from '@tanstack/react-table';
import type { PayrollStatementTableRow } from '@/features/finances/types/finance-employee.types';

export function createPayrollListColumns(): ColumnDef<PayrollStatementTableRow>[] {
    return [
        {
            accessorKey: 'month',
            header: () => (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    شهر
                </div>
            ),
            cell: ({ row }) => (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    {row.original.month}
                </div>
            ),
        },
        {
            accessorKey: 'payDate',
            header: () => (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    تاريخ الدفع
                </div>
            ),
            cell: ({ row }) => (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    {row.original.payDate}
                </div>
            ),
        },
        {
            accessorKey: 'netSalary',
            header: () => (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    صافي الراتب
                </div>
            ),
            cell: ({ row }) => (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] tabular-nums">
                    {row.original.netSalary} ريال
                </div>
            ),
        },
        {
            accessorKey: 'status',
            header: () => (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الحالة
                </div>
            ),
            cell: ({ row }) => (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.status}
                </div>
            ),
        },
    ];
}
