import { cn } from '@/lib/utils';
import { useEffect } from 'react';
import AllowancesAndBonusesTab from './AllowancesAndBonusesTab';
import BankAccountInfoTab from './BankAccountInfoTab';
import DeductionsAndTaxesTab from './DeductionsAndTaxesTab';
import FinancesTabPlaceholder from './FinancesTabPlaceholder';
import { FINANCE_TABS } from '../../data/financeTabs';
import PayrollStatements from './PayrollStatements';
import { useSearchParams } from 'react-router-dom';

type Props = {
    onSectionChange: (id: number) => void;
};

type FinanceTab = 'finance' | 'allowances' | 'benefits' | 'deductions' | 'bank';

/** يطابق `FINANCE_TABS` حسب `id` */
const TAB_ID_TO_SLUG: Record<number, FinanceTab> = {
    1: 'finance',
    2: 'benefits',
    3: 'allowances',
    4: 'deductions',
    5: 'bank',
};

const SLUG_TO_TAB_ID: Record<FinanceTab, number> = {
    finance: 1,
    benefits: 2,
    allowances: 3,
    deductions: 4,
    bank: 5,
};

function tabSlugFromSearchParams(searchParams: URLSearchParams, financeParam: string | null): FinanceTab {
    if (financeParam) return 'finance';
    const t = searchParams.get('tab');
    if (t === 'allowances' || t === 'benefits' || t === 'deductions' || t === 'bank' || t === 'finance') return t;
    return 'finance';
}

export default function SelectabelContent({ onSectionChange }: Props) {
    const [searchParams, setSearchParams] = useSearchParams();
    const financeParam = searchParams.get('finance');

    const activeTab = tabSlugFromSearchParams(searchParams, financeParam);

    useEffect(() => {
        onSectionChange(SLUG_TO_TAB_ID[activeTab]);
    }, [activeTab, onSectionChange]);

    const handleSelect = (value: FinanceTab) => {
        setSearchParams(
            (prev) => {
                const next = new URLSearchParams(prev);
                if (value === 'finance') {
                    next.delete('tab');
                    next.delete('finance');
                } else {
                    next.set('tab', value);
                    next.delete('finance');
                }
                return next;
            },
            { replace: true },
        );
    };

    return (
        <div className="w-full mt-6" dir="rtl">
            <div className="w-full flex flex-row items-stretch gap-[1px]">
                {FINANCE_TABS.map((tab, index) => (
                    <button
                        key={tab.id}
                        type="button"
                        onClick={() => handleSelect(TAB_ID_TO_SLUG[tab.id])}
                        className={cn(
                            'w-full transition-colors text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal font-cairo',
                            index === 0 && 'rounded-s-lg',
                            index === FINANCE_TABS.length - 1 && 'rounded-e-lg',
                            {
                                'bg-primery-blue-700': activeTab === TAB_ID_TO_SLUG[tab.id],
                                'bg-primery-blue-400 hover:bg-primery-blue-500': activeTab !== TAB_ID_TO_SLUG[tab.id],
                            },
                        )}
                    >
                        {tab.label}
                    </button>
                ))}
            </div>

            {activeTab === 'finance' && <PayrollStatements />}
            {activeTab === 'allowances' && <AllowancesAndBonusesTab />}
            {activeTab === 'benefits' && <FinancesTabPlaceholder />}
            {activeTab === 'deductions' && <DeductionsAndTaxesTab />}
            {activeTab === 'bank' && <BankAccountInfoTab />}
        </div>
    );
}
