import { useEffect, useMemo, useState } from 'react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { cn } from '@/lib/utils';
import FinancesSummaryCards from '../FinancesSummaryCards';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { formatMoneySar } from '@/features/finances/utils/formatMoney';

type AllowanceStatus = 'received' | 'pending' | 'suspended';

function mapStatus(raw: string | null | undefined): AllowanceStatus {
    const s = (raw || '').toLowerCase();
    if (s === 'approved' || s === 'active' || s === 'received' || s === 'paid' || s === 'مستلم') return 'received';
    if (s === 'pending' || s === 'قيد' || s === 'waiting') return 'pending';
    return 'suspended';
}

function StatusBadge({ status }: { status: AllowanceStatus }) {
    const map = {
        received: { text: 'مستلم', className: 'bg-[#22AD5C] text-white-blue-50' },
        pending: { text: 'قيد الانتظار', className: 'bg-amber-500 text-white-blue-50' },
        suspended: { text: 'معلق', className: 'bg-[#E81E1E] text-white-blue-50' },
    } as const;
    const st = map[status];
    return <span className={cn('inline-flex px-2 py-1 rounded-md text-xs font-semibold', st.className)}>{st.text}</span>;
}

type AllowanceRow = {
    id: number;
    type: string;
    amount: string;
    due: string;
    status: AllowanceStatus;
};

export default function AllowancesAndBonusesTab() {
    const [filter, setFilter] = useState<'all' | 'monthly' | 'yearly'>('all');
    const [rows, setRows] = useState<AllowanceRow[]>([]);
    const [yearlyTotal, setYearlyTotal] = useState('0');
    const [monthTotal, setMonthTotal] = useState('0');
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            setLoading(true);
            setError(null);
            try {
                const res = await apiGet<{
                    data: {
                        yearly_total_allowances?: number | string;
                        this_month_allowances?: number | string;
                        allowances?: Array<{
                            id: number;
                            name?: string | null;
                            amount?: number | string | null;
                            date?: string | null;
                            created_at?: string | null;
                            status?: string | null;
                        }>;
                    };
                }>({ endpoint: endpoints.financeEmployee.allowancesMe });
                if (cancelled) return;
                const d = res.data.data;
                setYearlyTotal(formatMoneySar(d?.yearly_total_allowances ?? 0));
                setMonthTotal(formatMoneySar(d?.this_month_allowances ?? 0));
                const rawList = d?.allowances ?? [];
                const list = Array.isArray(rawList) ? rawList : Object.values(rawList);
                const mapped: AllowanceRow[] = list.map((a) => ({
                    id: a.id,
                    type: a.name || 'بدل',
                    amount: `${formatMoneySar(a.amount)} ريال`,
                    due: a.date || (a.created_at ? String(a.created_at).slice(0, 10) : '—'),
                    status: mapStatus(a.status),
                }));
                setRows(mapped);
            } catch {
                if (!cancelled) {
                    setError('تعذر تحميل بيانات البدلات.');
                    setRows([]);
                }
            } finally {
                if (!cancelled) setLoading(false);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    /** فلتر القائمة — الـ API الحالي لا يفرّق نوع البدل؛ نعرض كل السجلات لكل الخيارات. */
    const filteredRows = rows;

    const summaryCards = useMemo(
        () => [
            { title: 'إجمالي البدلات الشهرية', value: monthTotal, unit: 'ريال' },
            { title: 'إجمالي العلاوات السنوية', value: yearlyTotal, unit: 'ريال' },
            { title: 'المكافآت الإضافية', value: '—', unit: '' },
        ],
        [monthTotal, yearlyTotal],
    );

    return (
        <div className="w-full mt-6 space-y-6 font-cairo">
            {error && <p className="text-sm text-red-600">{error}</p>}
            <FinancesSummaryCards cards={summaryCards} />

            <div className="rounded-xl border border-[#E8E7EA] bg-white-blue-50 shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A] overflow-hidden">
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 px-4 py-3 border-b border-[#E8E7EA] bg-white-blue-100/80">
                    <h3 className="text-base font-bold text-primery-blue-500">قائمة البدلات</h3>
                    <div className="flex items-center gap-2 min-w-[160px]">
                        <span className="text-sm text-[#625E74] whitespace-nowrap">القائمة</span>
                        <Select
                            value={filter}
                            onValueChange={(v) => setFilter(v as 'all' | 'monthly' | 'yearly')}
                        >
                            <SelectTrigger className="h-9 bg-white border-primery-blue-100 text-sm font-cairo">
                                <SelectValue placeholder="القائمة" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">جميع البدلات</SelectItem>
                                <SelectItem value="monthly">شهرية</SelectItem>
                                <SelectItem value="yearly">سنوية</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full min-w-[640px] text-sm">
                        <thead>
                            <tr className="bg-white-blue-100">
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">
                                    نوع البدل
                                </th>
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">
                                    المبلغ الشهري
                                </th>
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">
                                    تاريخ الاستحقاق
                                </th>
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">الحالة</th>
                            </tr>
                        </thead>
                        <tbody>
                            {loading ? (
                                <tr>
                                    <td colSpan={4} className="px-4 py-8 text-center text-[#625E74]">
                                        جاري التحميل…
                                    </td>
                                </tr>
                            ) : filteredRows.length === 0 ? (
                                <tr>
                                    <td colSpan={4} className="px-4 py-8 text-center text-[#625E74]">
                                        لا توجد بدلات مسجلة.
                                    </td>
                                </tr>
                            ) : (
                                filteredRows.map((row) => (
                                    <tr
                                        key={row.id}
                                        className="border-t border-[#E8E7EA] text-[#625E74] hover:bg-white-blue-100/50"
                                    >
                                        <td className="px-4 py-3 font-medium">{row.type}</td>
                                        <td className="px-4 py-3 tabular-nums">{row.amount}</td>
                                        <td className="px-4 py-3">{row.due}</td>
                                        <td className="px-4 py-3">
                                            <StatusBadge status={row.status} />
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}
