import { useEffect, useState } from 'react';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import CalendarIcon from '@/components/icons/CalendarIcon';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';

const readOnlyClass = 'bg-[#F3F4F6] border-[#E5E7EB] text-[#374151] cursor-default';

type BankPayload = {
    bank_name?: string | null;
    iban_number?: string | null;
    account_name?: string | null;
    account_number?: string | null;
    end_date?: string | null;
    bank_branch?: string | null;
    bank_address?: string | null;
};

export default function BankAccountInfoTab() {
    const [bank, setBank] = useState<BankPayload | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            setLoading(true);
            setError(null);
            try {
                const res = await apiGet<{ data: { bank_account?: BankPayload | null } }>({
                    endpoint: endpoints.financeEmployee.bankAccountsMe,
                });
                if (cancelled) return;
                setBank(res.data.data?.bank_account ?? null);
            } catch {
                if (!cancelled) setError('تعذر تحميل بيانات الحساب البنكي.');
            } finally {
                if (!cancelled) setLoading(false);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    const endDateDisplay = bank?.end_date
        ? String(bank.end_date).includes('T')
            ? String(bank.end_date).slice(0, 10)
            : String(bank.end_date)
        : '—';

    return (
        <div className="w-full mt-6 font-cairo">
            {error && <p className="text-sm text-red-600 mb-4">{error}</p>}
            <div className="rounded-xl border border-[#E8E7EA] bg-white-blue-50 shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A] p-6 md:p-8">
                {loading ? (
                    <p className="text-center text-[#625E74] py-8">جاري التحميل…</p>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
                        <div className="space-y-2">
                            <Label className="text-primery-blue-900 font-medium text-[15px]">اسم البنك</Label>
                            <Input readOnly value={bank?.bank_name ?? '—'} className={readOnlyClass} />
                        </div>
                        <div className="space-y-2">
                            <Label className="text-primery-blue-900 font-medium text-[15px]">رقم الآيبان</Label>
                            <Input readOnly value={bank?.iban_number ?? '—'} className={readOnlyClass} />
                        </div>
                        <div className="space-y-2">
                            <Label className="text-primery-blue-900 font-medium text-[15px]">اسم صاحب الحساب</Label>
                            <Input readOnly value={bank?.account_name ?? '—'} className={readOnlyClass} />
                        </div>
                        <div className="space-y-2">
                            <Label className="text-primery-blue-900 font-medium text-[15px]">تاريخ انتهاء الهوية / البطاقة</Label>
                            <div className="relative">
                                <Input readOnly value={endDateDisplay} className={`${readOnlyClass} pe-10`} />
                                <CalendarIcon
                                    width="20"
                                    height="20"
                                    className="absolute end-3 top-1/2 -translate-y-1/2 text-primery-blue-400 pointer-events-none"
                                />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <Label className="text-primery-blue-900 font-medium text-[15px]">فرع البنك</Label>
                            <Input readOnly value={bank?.bank_branch ?? '—'} className={readOnlyClass} />
                        </div>
                        <div className="space-y-2">
                            <Label className="text-primery-blue-900 font-medium text-[15px]">العنوان / الحي</Label>
                            <Input readOnly value={bank?.bank_address ?? '—'} className={readOnlyClass} />
                        </div>
                        {bank?.account_number ? (
                            <div className="space-y-2 md:col-span-2">
                                <Label className="text-primery-blue-900 font-medium text-[15px]">رقم الحساب</Label>
                                <Input readOnly value={bank.account_number} className={readOnlyClass} />
                            </div>
                        ) : null}
                    </div>
                )}
            </div>
        </div>
    );
}
