import { cn } from '@/lib/utils';

export type FinanceDetailRow = {
    label: string;
    /** نص القيمة كما يُعرض، مثال: "10,000 ريال" */
    value: string;
};

type FinancesDetailsTableProps = {
    title: string;
    rows: FinanceDetailRow[];
    className?: string;
};

/**
 * جدول تفاصيل ثنائي الأعمدة (عنوان يمين + قيمة يسار) — مناسب لـ RTL
 */
export default function FinancesDetailsTable({ title, rows, className }: FinancesDetailsTableProps) {
    return (
        <div
            className={cn(
                'rounded-xl border border-[#E8E7EA] bg-white-blue-50 overflow-hidden shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]',
                className,
            )}
        >
            <div className="px-4 pt-4 pb-2">
                <h3 className="font-cairo font-bold text-base text-primery-blue-700 pb-2 border-b-2 border-primery-blue-700 w-fit max-w-full">
                    {title}
                </h3>
            </div>
            <div className="divide-y divide-[#E8E7EA]">
                {rows.map((row) => (
                    <div key={row.label} className="grid grid-cols-2 font-cairo">
                        <div className="bg-[#F0F2F5] px-4 py-3 text-sm font-medium text-primery-blue-600 leading-relaxed">
                            {row.label}
                        </div>
                        <div className="bg-white-blue-50 px-4 py-3 text-sm text-[#1F2937] tabular-nums leading-relaxed">
                            {row.value}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}
