import { useState } from 'react';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import FileDownloadIcon from '@/components/icons/file/FileDownloadIcon';
import EditIcon from '@/components/icons/EditIcon';
import SelectabelContent from '../components/tabs/SelectabelContent';
import { getFinancePrimaryAction, getFinanceTabHeading } from '../data/financeTabs';

const FinancesPage = () => {
    const [activeSection, setActiveSection] = useState(1);
    const primaryAction = getFinancePrimaryAction(activeSection);

    return (
        <div className="w-full mt-6 mb-24 px-1 sm:px-0">
            <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
                <UnderlineHeading text={getFinanceTabHeading(activeSection)} className="text-start" />
                {primaryAction.type === 'download' ? (
                    <button
                        type="button"
                        className="inline-flex items-center justify-center gap-2 self-start lg:self-auto px-[14px] py-2.5 rounded-lg bg-primery-blue-50 border border-primery-blue-100 shadow-[0px_1px_2px_0px_#1018280D] text-primery-blue-600 hover:bg-primery-blue-100/80 transition-colors font-cairo text-sm font-semibold whitespace-nowrap"
                    >
                        <FileDownloadIcon className="text-primery-blue-600 shrink-0" width="18" height="19" />
                        {primaryAction.label}
                    </button>
                ) : (
                    <button
                        type="button"
                        className="inline-flex items-center justify-center gap-2 self-start lg:self-auto px-[14px] py-2.5 rounded-lg bg-primery-blue-50 border border-primery-blue-100 shadow-[0px_1px_2px_0px_#1018280D] text-primery-blue-600 hover:bg-primery-blue-100/80 transition-colors font-cairo text-sm font-semibold whitespace-nowrap"
                    >
                        <EditIcon width="18" height="18" className="text-primery-blue-600 shrink-0" />
                        {primaryAction.label}
                    </button>
                )}
            </div>
            <SelectabelContent onSectionChange={setActiveSection} />
        </div>
    );
};

export default FinancesPage;
